sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float blurLength;
uniform float angle;
half4 main(float2 coord) {
    float reach = clamp(abs(blurLength), 0.0, 1.0);
    if (reach < 0.001) return image.eval(coord);
    float rad = radians(angle);
    float2 direction = float2(cos(rad), -sin(rad));
    float distance = reach * length(size);
    float2 delta = direction * (distance / 64.0);
    float2 lo = float2(0.5);
    float2 hi = max(size - 0.5, lo);
    half4 sum = half4(0.0);
    for (int i = 0; i < 65; i++) {
        float2 p = coord + delta * (float(i) - 32.0);
        float inside = step(0.0, p.x) * step(p.x, size.x) * step(0.0, p.y) * step(p.y, size.y);
        sum += image.eval(clamp(p, lo, hi)) * inside;
    }
    return sum / 65.0;
}
